import React, { useState, useRef } from "react";
import axios from "axios";
import QRCode from "react-qr-code";
import { useLocation } from "react-router-dom";
import Navbar from "./Navbar";
import html2canvas from "html2canvas";

function Register() {
  const location = useLocation();

  const eventId = location.state?.eventId || "";
  const eventName = location.state?.eventName || "No Event Selected";

  const [formData, setFormData] = useState({
    name: "",
    college_name: "",
    phone: "",
    email: "",
    event_id: eventId,
  });

  const [userId, setUserId] = useState("");
  const [qrData, setQrData] = useState("");
  const [photo, setPhoto] = useState("");
  const [showPayment, setShowPayment] = useState(false);
  const [utrNumber, setUtrNumber] = useState("");
  const [verifying, setVerifying] = useState(false);
  const [utrError, setUtrError] = useState("");

  const videoRef = useRef(null);
  const canvasRef = useRef(null);
  const idCardRef = useRef(null);
  const streamRef = useRef(null);

  /* ── UPI Details ─────────────────────────── */
  const YOUR_UPI_ID = "arunsekar664@okaxis";
  const AMOUNT = "1";
  const PAYEE_NAME = "CollegeEvent";
  /* ─────────────────────────────────────────── */

  const upiQRValue = `upi://pay?pa=${YOUR_UPI_ID}&pn=${encodeURIComponent(PAYEE_NAME)}&am=${AMOUNT}&cu=INR`;

  /* =============================
     INPUT CHANGE
  ============================= */
  const handleChange = (e) => {
    setFormData({ ...formData, [e.target.name]: e.target.value });
  };

  /* =============================
     SHOW PAYMENT SCREEN
  ============================= */
  const handleShowPayment = (e) => {
    e.preventDefault();
    setShowPayment(true);
    setUtrError("");
  };

  /* =============================
     UTR VALIDATION (basic format check)
     Real UPI UTR = 12 digits (all numeric)
     Some apps show alphanumeric ref IDs (min 10 chars)
  ============================= */
  const isValidUTRFormat = (utr) => {
    const trimmed = utr.trim();
    if (trimmed.length < 10 || trimmed.length > 22) return false;
    // Must be alphanumeric only (no spaces, no special chars)
    if (!/^[a-zA-Z0-9]+$/.test(trimmed)) return false;
    return true;
  };

  /* =============================
     VERIFY UTR + REGISTER
  ============================= */
  const verifyAndRegister = async () => {
    setUtrError("");

    const trimmedUTR = utrNumber.trim();

    // Client-side format check
    if (!trimmedUTR) {
      setUtrError("Please enter your UTR / Transaction ID.");
      return;
    }

    if (!isValidUTRFormat(trimmedUTR)) {
      setUtrError(
        "Invalid UTR format. UTR must be 10–22 alphanumeric characters with no spaces or special characters. Please check and try again.",
      );
      return;
    }

    setVerifying(true);

    try {
      const res = await axios.post("http://localhost:5000/verify-utr", {
        utrNumber: trimmedUTR,
        amount: AMOUNT,
        ...formData,
        photo,
      });

      if (res.data.success) {
        setUserId(res.data.userId);
        setQrData(res.data.qrData);
        setUtrError("");
        alert("✅ Payment Verified! Registration Successful.");
      } else {
        // Show specific error from backend (duplicate / fake / not found)
        setUtrError(
          res.data.message || "Verification failed. Please try again.",
        );
      }
    } catch {
      setUtrError("Server error. Please try again or contact support.");
    } finally {
      setVerifying(false);
    }
  };

  /* =============================
     OPEN CAMERA
  ============================= */
  const openCamera = async () => {
    try {
      const stream = await navigator.mediaDevices.getUserMedia({
        video: true,
        audio: false,
      });
      streamRef.current = stream;
      videoRef.current.srcObject = stream;
      videoRef.current.play();
    } catch {
      alert("Camera access denied");
    }
  };

  /* =============================
     CAPTURE PHOTO
  ============================= */
  const capturePhoto = () => {
    const video = videoRef.current;
    const canvas = canvasRef.current;
    canvas.width = video.videoWidth;
    canvas.height = video.videoHeight;
    canvas.getContext("2d").drawImage(video, 0, 0);
    setPhoto(canvas.toDataURL("image/png"));
    if (streamRef.current) {
      streamRef.current.getTracks().forEach((t) => t.stop());
    }
  };

  /* =============================
     DOWNLOAD ID CARD
  ============================= */
  const downloadCard = () => {
    html2canvas(idCardRef.current).then((canvas) => {
      const link = document.createElement("a");
      link.download = "Event_ID_Card.png";
      link.href = canvas.toDataURL();
      link.click();
    });
  };

  /* =============================
     STYLES
  ============================= */
  const styles = {
    page: {
      minHeight: "100vh",
      backgroundColor: "#f3f4f6",
    },
    container: {
      maxWidth: "480px",
      margin: "0 auto",
      padding: "24px 16px",
      textAlign: "center",
    },
    title: {
      fontSize: "24px",
      fontWeight: "700",
      color: "#111827",
      marginBottom: "6px",
    },
    subtitle: {
      fontSize: "14px",
      color: "#6b7280",
      marginBottom: "24px",
    },
    card: {
      background: "#ffffff",
      borderRadius: "14px",
      padding: "24px",
      marginBottom: "16px",
      boxShadow: "0 1px 4px rgba(0,0,0,0.08)",
      textAlign: "left",
    },
    input: {
      width: "100%",
      padding: "12px 14px",
      fontSize: "14px",
      borderRadius: "8px",
      border: "1px solid #d1d5db",
      marginBottom: "12px",
      boxSizing: "border-box",
      outline: "none",
      backgroundColor: "#fafafa",
    },
    primaryBtn: {
      width: "100%",
      padding: "14px",
      backgroundColor: "#4f46e5",
      color: "#fff",
      border: "none",
      borderRadius: "10px",
      fontSize: "15px",
      fontWeight: "700",
      cursor: "pointer",
      marginTop: "8px",
    },
    verifyBtn: (disabled) => ({
      width: "100%",
      padding: "14px",
      backgroundColor: disabled ? "#9ca3af" : "#16a34a",
      color: "#fff",
      border: "none",
      borderRadius: "10px",
      fontSize: "15px",
      fontWeight: "700",
      cursor: disabled ? "not-allowed" : "pointer",
      marginTop: "4px",
    }),
    errorBox: {
      backgroundColor: "#fef2f2",
      border: "1px solid #fca5a5",
      borderRadius: "8px",
      padding: "10px 14px",
      marginBottom: "12px",
      fontSize: "13px",
      color: "#b91c1c",
      textAlign: "left",
    },
    infoBox: {
      backgroundColor: "#eff6ff",
      border: "1px solid #bfdbfe",
      borderRadius: "8px",
      padding: "10px 14px",
      marginBottom: "16px",
      fontSize: "13px",
      color: "#1e40af",
      textAlign: "left",
    },
    label: {
      fontSize: "13px",
      fontWeight: "600",
      color: "#374151",
      marginBottom: "6px",
      display: "block",
    },
    hint: {
      fontSize: "12px",
      color: "#9ca3af",
      marginBottom: "10px",
    },
    divider: {
      border: "none",
      borderTop: "1px solid #e5e7eb",
      margin: "20px 0",
    },
    backBtn: {
      background: "none",
      border: "none",
      color: "#6b7280",
      cursor: "pointer",
      textDecoration: "underline",
      fontSize: "13px",
      marginTop: "12px",
      display: "block",
      width: "100%",
      textAlign: "center",
    },
    qrWrapper: {
      display: "flex",
      flexDirection: "column",
      alignItems: "center",
      backgroundColor: "#f9fafb",
      border: "1px solid #e5e7eb",
      borderRadius: "12px",
      padding: "20px",
      marginBottom: "16px",
    },
    upiTag: {
      marginTop: "12px",
      fontSize: "12px",
      color: "#6b7280",
    },
    upiId: {
      fontWeight: "600",
      color: "#111827",
      fontSize: "13px",
    },
    idCard: {
      border: "2px solid #4f46e5",
      width: "300px",
      margin: "auto",
      padding: "20px",
      borderRadius: "14px",
      backgroundColor: "#ffffff",
      boxShadow: "0 4px 12px rgba(79,70,229,0.15)",
    },
  };

  return (
    <div style={styles.page}>
      <Navbar />

      <div style={styles.container}>
        <h2 style={styles.title}>Event Registration</h2>
        <p style={styles.subtitle}>
          Fill the form and complete ₹{AMOUNT} payment to register
        </p>

        {/* ══════════════════════════════
            STEP 1 — REGISTRATION FORM
        ══════════════════════════════ */}
        {!showPayment && !qrData && (
          <form onSubmit={handleShowPayment}>
            <div style={styles.card}>
              <label style={styles.label}>Full Name</label>
              <input
                style={styles.input}
                name="name"
                placeholder="Enter your name"
                onChange={handleChange}
                required
              />

              <label style={styles.label}>College Name</label>
              <input
                style={styles.input}
                name="college_name"
                placeholder="Enter college name"
                onChange={handleChange}
                required
              />

              <label style={styles.label}>Phone Number</label>
              <input
                style={styles.input}
                name="phone"
                placeholder="Enter phone number"
                onChange={handleChange}
                required
              />

              <label style={styles.label}>Email Address</label>
              <input
                style={styles.input}
                name="email"
                placeholder="Enter email address"
                onChange={handleChange}
                required
              />

              <div
                style={{
                  backgroundColor: "#f0fdf4",
                  border: "1px solid #86efac",
                  borderRadius: "8px",
                  padding: "10px 14px",
                  marginBottom: "12px",
                  fontSize: "13px",
                  color: "#166534",
                }}
              >
                Selected Event: <strong>{eventName}</strong>
              </div>

              <button type="submit" style={styles.primaryBtn}>
                Proceed to Pay ₹{AMOUNT}
              </button>
            </div>
          </form>
        )}

        {/* ══════════════════════════════
            STEP 2 — PAYMENT (QR ONLY)
        ══════════════════════════════ */}
        {showPayment && !qrData && (
          <div>
            {/* QR Code Card */}
            <div style={styles.card}>
              <p
                style={{
                  ...styles.label,
                  fontSize: "15px",
                  marginBottom: "4px",
                }}
              >
                Scan QR &amp; Pay ₹{AMOUNT}
              </p>
              <p style={styles.hint}>
                Open GPay / PhonePe / Paytm → Scan QR → Pay ₹{AMOUNT}
              </p>

              <div style={styles.qrWrapper}>
                <div
                  style={{
                    padding: "12px",
                    backgroundColor: "#ffffff",
                    borderRadius: "10px",
                    border: "1px solid #e5e7eb",
                  }}
                >
                  <QRCode value={upiQRValue} size={180} />
                </div>
                <p style={styles.upiTag}>
                  UPI ID: <span style={styles.upiId}>{YOUR_UPI_ID}</span>
                </p>
                <p style={{ ...styles.upiTag, marginTop: "4px" }}>
                  Amount: <span style={styles.upiId}>₹{AMOUNT}</span>
                </p>
              </div>

              <div style={styles.infoBox}>
                <strong>How to pay:</strong>
                <br />
                1. Open any UPI app (GPay / PhonePe / Paytm)
                <br />
                2. Tap <strong>Scan QR</strong> and scan the code above
                <br />
                3. Confirm the payment of ₹{AMOUNT}
                <br />
                4. Note your <strong>UTR / Transaction ID</strong> from the app
              </div>
            </div>

            {/* UTR Entry Card */}
            <div style={styles.card}>
              <label style={styles.label}>Enter UTR / Transaction ID</label>
              <p style={styles.hint}>
                GPay → UPI Ref. No. &nbsp;|&nbsp; PhonePe → Transaction ID
                &nbsp;|&nbsp; Paytm → UTR Number &nbsp;|&nbsp; Or check your
                bank SMS
              </p>

              {/* Error alert */}
              {utrError && <div style={styles.errorBox}>⚠️ {utrError}</div>}

              <input
                type="text"
                placeholder="Enter UTR / Transaction ID"
                value={utrNumber}
                onChange={(e) => {
                  setUtrError("");
                  setUtrNumber(e.target.value.replace(/\s/g, "").slice(0, 22));
                }}
                style={{
                  ...styles.input,
                  border: utrError ? "1px solid #f87171" : "1px solid #d1d5db",
                  letterSpacing: "1px",
                  marginBottom: "8px",
                }}
              />

              <button
                onClick={verifyAndRegister}
                disabled={verifying || utrNumber.trim().length < 10}
                style={styles.verifyBtn(
                  verifying || utrNumber.trim().length < 10,
                )}
              >
                {verifying ? "Verifying..." : "Verify & Get ID Card"}
              </button>
            </div>

            <button
              onClick={() => {
                setShowPayment(false);
                setUtrNumber("");
                setUtrError("");
              }}
              style={styles.backBtn}
            >
              ← Back to Form
            </button>
          </div>
        )}

        {/* ══════════════════════════════
            STEP 3 — QR CODE + CAMERA
        ══════════════════════════════ */}
        {qrData && !photo && (
          <div style={styles.card}>
            <p style={{ ...styles.label, fontSize: "15px" }}>
              Your Registration QR Code
            </p>
            <div
              style={{
                display: "flex",
                justifyContent: "center",
                marginBottom: "20px",
              }}
            >
              <QRCode value={qrData.toString()} size={200} />
            </div>

            <button
              onClick={openCamera}
              style={{ ...styles.primaryBtn, marginBottom: "12px" }}
            >
              Open Camera for Photo
            </button>

            <video
              ref={videoRef}
              width="100%"
              style={{
                borderRadius: "8px",
                border: "1px solid #e5e7eb",
                display: "block",
              }}
            />

            <button
              onClick={capturePhoto}
              style={{
                ...styles.primaryBtn,
                backgroundColor: "#0891b2",
                marginTop: "12px",
              }}
            >
              Capture Photo
            </button>

            <canvas ref={canvasRef} style={{ display: "none" }} />
          </div>
        )}

        {/* ══════════════════════════════
            STEP 4 — ID CARD
        ══════════════════════════════ */}
        {photo && (
          <div style={{ marginTop: "10px" }}>
            <p
              style={{ ...styles.label, fontSize: "15px", textAlign: "center" }}
            >
              Your Event ID Card
            </p>

            <div ref={idCardRef} style={styles.idCard}>
              <h3
                style={{
                  color: "#4f46e5",
                  marginBottom: "12px",
                  fontSize: "16px",
                }}
              >
                College Event ID Card
              </h3>
              <p style={{ fontSize: "14px", marginBottom: "6px" }}>
                <strong>Name:</strong> {formData.name}
              </p>
              <p style={{ fontSize: "14px", marginBottom: "6px" }}>
                <strong>User ID:</strong> {userId}
              </p>
              <p style={{ fontSize: "14px", marginBottom: "14px" }}>
                <strong>Event:</strong> {eventName}
              </p>

              <div
                style={{
                  display: "flex",
                  justifyContent: "center",
                  marginBottom: "14px",
                }}
              >
                <QRCode value={qrData.toString()} size={120} />
              </div>

              <div style={{ display: "flex", justifyContent: "center" }}>
                <img
                  src={photo}
                  alt="User"
                  width="110"
                  style={{ borderRadius: "8px", border: "2px solid #e5e7eb" }}
                />
              </div>
            </div>

            <button
              onClick={downloadCard}
              style={{
                ...styles.primaryBtn,
                marginTop: "16px",
                backgroundColor: "#16a34a",
              }}
            >
              Download ID Card
            </button>
          </div>
        )}
      </div>
    </div>
  );
}

export default Register;
